class TreeCursor {
  private vals: number[] = [];
  private pos = 0;

  constructor(root: TreeNode | null) {
    const stack: TreeNode[] = [];
    let node = root;
    while (node || stack.length) {
      while (node) { stack.push(node); node = node.left; }
      node = stack.pop()!;
      this.vals.push(node.val);
      node = node.right;
    }
  }

  next(): number {
    return this.vals[this.pos++];
  }

  hasNext(): boolean {
    return this.pos < this.vals.length;
  }
}

